object "ClawBrain" {
    @behavior_tree {
      root: {
        type: "sequence",
        name: "holoclaw_cycle",
        children: [

          // ── Phase 0: Load Wisdom ──
          // On first tick, loads accumulated wisdom from previous sessions.
          // Subsequent ticks skip if wisdom already loaded (blackboard check).
          {
            type: "selector",
            name: "wisdom_gate",
            children: [
              {
                type: "condition",
                name: "wisdom_loaded",
                condition: "wisdom_loaded"
              },
              {
                type: "action",
                name: "load_wisdom",
                action: "identity_intake"
              }
            ]
          },

          // ── Phase 1: Work Router ──
          // Selector tries each path in priority order.
          // First success wins; if all fail, the cycle still completes.
          {
            type: "selector",
            name: "work_router",
            children: [

              // Path A: Inbox — check for messages from Discord/Slack/manual
              {
                type: "sequence",
                name: "inbox_path",
                children: [
                  {
                    type: "action",
                    name: "check_inbox",
                    action: "channel_ingest"
                  },
                  {
                    type: "action",
                    name: "ack_message",
                    action: "channel_send",
                    params: {
                      channel: "inbox-ack",
                      message: "holoclaw: message received and queued for processing"
                    }
                  }
                ]
              },

              // Path B: Health Check — proactive codebase monitoring
              // Runs when no inbox messages (channel_ingest failed above).
              // Rate limiter throttles frequency. If tsc exits non-zero
              // (type errors exist), shell_exec returns false and the
              // selector falls through to the heartbeat.
              {
                type: "sequence",
                name: "health_path",
                children: [
                  {
                    type: "action",
                    name: "run_typecheck",
                    action: "shell_exec",
                    params: {
                      command: "npx",
                      args: ["tsc", "--noEmit", "--pretty", "false"],
                      timeoutMs: 90000
                    }
                  },
                  {
                    type: "action",
                    name: "report_health",
                    action: "channel_send",
                    params: {
                      channel: "health",
                      message: "holoclaw: health check complete"
                    }
                  }
                ]
              },

              // Path C: Heartbeat — default fallback, just prove we're alive
              {
                type: "action",
                name: "heartbeat",
                action: "channel_send",
                params: {
                  channel: "heartbeat",
                  message: "holoclaw: alive"
                }
              }
            ]
          }
        ]
      },

      tick_rate: 1,
      restart_on_complete: true,

      blackboard: {
        // Wisdom tracking
        wisdom_loaded: false,
        wisdom: null,
        wisdomCount: 0,

        // Inbox state
        channel_message: null,
        channel_ingest_ok: false,

        // Shell exec results
        shell_exec_code: -1,
        shell_exec_stdout: "",
        shell_exec_stderr: "",

        // Cycle counter
        cycle_number: 0
      }
    }

    // ── Safety: Rate Limiter ──
    @rate_limiter {
      strategy: "token_bucket",
      max_tokens: 20,
      refill_rate: 5,
      window_ms: 60000,
      per_key: false
    }

    // ── Safety: Timeout Guard ──
    @timeout_guard {
      default_timeout_ms: 120000,
      fallback_action: "abort"
    }

    // ── Safety: Circuit Breaker ──
    @circuit_breaker {
      failure_threshold: 5,
      window_ms: 300000,
      reset_timeout_ms: 60000,
      success_threshold: 1,
      failure_rate_threshold: 0,
      min_requests: 5
    }

    // ── Economy: Budget Tracking ──
    @economy {
      initial_balance: 10,
      default_spend_limit: 2,
      spend_limit_period: 3600000,
      max_transaction_history: 200,
      escrow_enabled: false,
      task_completion_reward: 0.01
    }

    // ── Telemetry: Structured Logging ──
    @structured_logger {
      min_level: "info",
      max_entries: 1000,
      rotation_count: 200,
      emit_events: true,
      console_output: false,
      default_fields: {}
    }

    // ── Scheduler: Proactive Jobs ──
    // Health checks run naturally via the BT selector fallback.
    // Add scheduled jobs here when scheduler→blackboard bridge is built.
    @scheduler {
      jobs: [],
      max_jobs: 10,
      poll_interval_ms: 5000
    }
  }

description:
HoloDaemon — Customizable Resident Agent Runtime

HoloDaemon is the generic long-running agent container: identity, skills,
memory, scheduling, budgets, telemetry, and authority handles. HoloHeal is
the default self-improvement mission profile running on this runtime.

Architecture:
1. Dashboard surface — 2D operations view hydrated with live state
2. Behavior tree — orchestrates daemon cycles (intake → fix → verify → commit)
3. Agent pool — manages concurrent daemon workers with rate limiting
4. Telemetry feed — real-time metrics streamed to the UI

The legacy TypeScript runner continues to execute daemon jobs; this
composition provides the declarative control plane for many missions.

