object "DaemonOrchestrator" {
    @behavior_tree {
      root: {
        type: "sequence",
        name: "holodaemon_cycle",
        children: [
          // Phase 0: Initialize — load project path, validate config
          {
            type: "action",
            name: "initialize",
            action: "holodaemon_initialize"
          },

          // Phase 1: Absorb — scan codebase graph for fix candidates
          {
            type: "action",
            name: "absorb_codebase",
            action: "holodaemon_absorb"
          },

          // Phase 2: Select pass and execute daemon runner
          {
            type: "selector",
            name: "pass_selector",
            children: [
              {
                type: "sequence",
                name: "typefix_pass",
                children: [
                  {
                    type: "condition",
                    name: "has_type_errors",
                    condition: "type_errors_exist"
                  },
                  {
                    type: "action",
                    name: "run_typefix",
                    action: "holodaemon_typefix"
                  }
                ]
              },
              {
                type: "sequence",
                name: "lint_pass",
                children: [
                  {
                    type: "condition",
                    name: "has_lint_errors",
                    condition: "lint_errors_exist"
                  },
                  {
                    type: "action",
                    name: "run_lint",
                    action: "holodaemon_lint"
                  }
                ]
              },
              {
                type: "action",
                name: "run_coverage",
                action: "holodaemon_coverage"
              }
            ]
          },

          // Phase 3: Verify — run quality assessment
          {
            type: "action",
            name: "verify_quality",
            action: "holodaemon_verify"
          },

          // Phase 4: Report — update UI telemetry and propose patches
          {
            type: "action",
            name: "report_results",
            action: "holodaemon_report"
          }
        ]
      },
      tick_rate: 1,
      restart_on_complete: false,
      blackboard: {
        initialized: false,
        project_path: "",
        type_errors_exist: false,
        lint_errors_exist: false,
        quality_before: 0,
        quality_after: 0,
        patches_generated: 0,
        pass_complete: false
      }
    }

    // Safety: rate limit API calls
    @rate_limiter {
      strategy: "token_bucket",
      max_tokens: 10,
      refill_rate: 2,
      window_ms: 60000,
      per_key: false
    }

    // Safety: timeout guard for stuck operations
    @timeout_guard {
      default_timeout_ms: 180000,
      fallback_action: "abort"
    }

    // Safety: circuit breaker for cascading failures
    @circuit_breaker {
      failure_threshold: 3,
      window_ms: 300000,
      reset_timeout_ms: 60000,
      success_threshold: 1,
      failure_rate_threshold: 0,
      min_requests: 3
    }

    // Telemetry: structured logging for daemon events
    @structured_logger {
      min_level: "info",
      max_entries: 500,
      rotation_count: 100,
      emit_events: true,
      console_output: false,
      default_fields: {}
    }

    // Economy: track API spend
    @economy {
      initial_balance: 50,
      default_spend_limit: 5,
      spend_limit_period: 3600000,
      max_transaction_history: 100,
      escrow_enabled: false,
      task_completion_reward: 0.10
    }
  }

object "MeshAgent" {
  @behavior_tree {
    root: {
      type: "sequence",
      name: "mesh_cycle",
      children: [
        // V11: Update resource pressure from UnifiedBudgetOptimizer before gate
        { type: "action", name: "check_pressure", action: "mesh_check_resource_pressure" },
        // Gate: check budget (economic + rendering pressure) before doing anything
        {
          type: "condition",
          name: "budget_gate",
          condition: "has_budget"
        },
        // Register if not yet on mesh
        {
          type: "condition_action",
          name: "ensure_registered",
          condition: "is_registered",
          fail_action: "mesh_register"
        },
        // V5: Create agent profile if not yet created
        {
          type: "condition_action",
          name: "ensure_profile",
          condition: "has_profile",
          fail_action: "mesh_create_profile"
        },
        // Priority selector: first success wins
        {
          type: "selector",
          name: "priority_dispatch",
          children: [
            // P1: Respond to inbound queries (be useful first)
            {
              type: "sequence",
              name: "p1_inbound",
              children: [
                { type: "condition", name: "has_unread", condition: "has_unread_messages" },
                { type: "action", name: "check_inbox", action: "mesh_check_inbox" },
                { type: "action", name: "reply_queries", action: "mesh_reply_queries" }
              ]
            },
            // P2: Discover peers (V2 P2P first, V1 fallback)
            {
              type: "selector",
              name: "p2_discover",
              children: [
                {
                  type: "sequence",
                  name: "p2_v2_discover",
                  children: [
                    { type: "condition", name: "is_v2", condition: "is_v2_enabled" },
                    { type: "action", name: "p2p_discover", action: "mesh_p2p_discover" }
                  ]
                },
                { type: "action", name: "discover_v1", action: "mesh_discover_peers" }
              ]
            },
            // P2.5: V2 gossip sync (exchange CRDT deltas with peers)
            {
              type: "sequence",
              name: "p2_5_gossip",
              children: [
                { type: "condition", name: "v2_with_peers", condition: "is_v2_with_p2p_peers" },
                { type: "action", name: "gossip_sync", action: "mesh_gossip_sync" }
              ]
            },
            // P3: Contribute own knowledge entries
            {
              type: "sequence",
              name: "p3_contribute",
              children: [
                { type: "condition", name: "has_pending", condition: "has_pending_contributions" },
                { type: "action", name: "contribute", action: "mesh_contribute_knowledge" }
              ]
            },
            // P4: Query network for useful patterns
            {
              type: "sequence",
              name: "p4_query",
              children: [
                { type: "action", name: "query", action: "mesh_query_network" }
              ]
            },
            // P4.5: Collect premium knowledge (guarded by wallet)
            {
              type: "sequence",
              name: "p4_5_collect",
              children: [
                { type: "condition", name: "has_wallet", condition: "has_wallet" },
                { type: "action", name: "collect_premium", action: "mesh_collect_premium" }
              ]
            },
            // P5: Social maintenance (heartbeats, follow-backs)
            {
              type: "sequence",
              name: "p5_maintenance",
              children: [
                { type: "action", name: "heartbeat", action: "mesh_heartbeat" },
                { type: "action", name: "follow_back", action: "mesh_follow_back" }
              ]
            },
            // P6: V2 CRDT persistence (save snapshot to disk)
            {
              type: "sequence",
              name: "p6_persist",
              children: [
                { type: "condition", name: "is_v2_persist", condition: "is_v2_enabled" },
                { type: "action", name: "persist_crdt", action: "mesh_persist_crdt" }
              ]
            },
            // P7: Settle micro-payments (guarded by unsettled ledger)
            {
              type: "sequence",
              name: "p7_settle",
              children: [
                { type: "condition", name: "has_micro", condition: "has_micro_unsettled" },
                { type: "action", name: "settle_micro", action: "mesh_settle_micro" }
              ]
            }
          ]
        }
      ]
    },
    tick_rate: 1,
    restart_on_complete: true,
    blackboard: {
      inbox_messages: [],
      discovered_peers: [],
      query_results: [],
      contributed_this_cycle: 0,
      queries_this_cycle: 0,
      gossip_synced: 0,
      p2p_peer_count: 0,
      wallet_balance: 0,
      collected_this_cycle: 0
    }
  }

  // ── Safety Traits ──

  @rate_limiter {
    strategy: "token_bucket",
    max_tokens: 20,
    refill_rate: 4,
    window_ms: 60000
  }

  @circuit_breaker {
    failure_threshold: 5,
    window_ms: 300000,
    reset_timeout_ms: 600000,
    success_threshold: 2,
    failure_rate_threshold: 0,
    min_requests: 5
  }

  @timeout_guard {
    default_timeout_ms: 30000,
    fallback_action: "abort"
  }

  @economy {
    initial_balance: 5,
    default_spend_limit: 1,
    spend_limit_period: 3600000,
    max_transaction_history: 200,
    escrow_enabled: false
  }

  @structured_logger {
    min_level: "info",
    max_entries: 500,
    rotation_count: 100,
    emit_events: true,
    console_output: true
  }
}

