          },

          // Phase 3: COMPRESS — Capture wisdom, patterns, gotchas
          {
            type: "action",
            name: "compress",
            action: "compress_knowledge"
          },

          // Phase 3.5: AUTO-INTAKE — Absorb own learnings immediately
          {
            type: "action",
            name: "auto_intake",
            action: "auto_intake"
          },

          // Phase 4: GROW — Evaluate consciousness, praise improvements
          {
            type: "sequence",
            name: "grow",
            children: [
              { type: "action", name: "evaluate_consciousness", action: "evaluate_consciousness" },
              { type: "action", name: "assess_regeneration", action: "assess_regeneration" },
              { type: "action", name: "celebrate", action: "praise_cycle" }
            ]
          }
        ]
      },
      tick_rate: 1,
      restart_on_complete: false,
      blackboard: {
        intake_complete: false,
        presencing_ready: false,
        knowledge_compressed: false,
        consciousness_evaluated: false,
        cycle_praised: false
      }
    }

    // Feedback loop: monitors positive energy and principle adherence
    @feedback_loop {
      metrics: {
        positive_energy: { target: 1.2, min: 0, max: 2.0 },
        emergence_ratio: { target: 0.8, min: 0, max: 1.0 },
        regenerative_health: { target: 0.7, min: 0, max: 1.0 },
        consciousness_progress: { target: 0.7, min: 0, max: 1.0 },
        shadow_integration: { target: 0.5, min: 0, max: 1.0 }
      },
      history_window: 20,
      alert_threshold: 25,
      critical_threshold: 60,
      auto_signal: true,
      min_samples_for_trend: 3
    }

    // Structured logger for motivation telemetry
    @structured_logger {
      min_level: "info",
      max_entries: 200,
      rotation_count: 50,
      emit_events: true,
      console_output: false,
      default_fields: {}
    }

    // Scheduler: periodic consciousness evaluation and praise cycles
    @scheduler {
      jobs: [
        {
          id: "consciousness_heartbeat",
          interval_ms: 600000,
          action: "motivation:evaluate_consciousness",
          params: {},
          mode: "repeat",
          max_executions: 0,
          paused: true
        },
        {
          id: "praise_cycle",
          interval_ms: 300000,
          action: "motivation:praise_cycle",
          params: {},
          mode: "repeat",
          max_executions: 0,
          paused: true
        }
      ],
      max_jobs: 5,
      poll_interval_ms: 1000
    }

    // Transform: normalize principle scores into feedback metrics
    @transform {
      rules: [
        {
          id: "principle_normalize",
          source_event: "motivation:principles_evaluated",
          output_event: "feedback:update_metric",
          ops: [
            { type: "pick", fields: ["emergence", "biomimicry", "positive_futures", "presencing", "regeneration", "wholeness"] },
            { type: "compute", field: "average", expr: "($emergence + $biomimicry + $positive_futures + $presencing + $regeneration + $wholeness) / 6" },
            { type: "default", field: "name", value: "consciousness_progress" }
          ],
          enabled: true
        }
      ]
    }
  }

object "RuntimeRequirements" {
    @runtime_requirements {
      min_vram_gb: 4,
      gpu_class_regex: ".*",
      min_reliability: 0.90,
      max_dph_total_usd: 0.30,
      preferred_disk_gb: 40,
      cpu_min_cores: 4,
      ram_min_gb: 8,
      headroom_gb: 2,
      reasoning: "Qwen2.5-0.5B-Instruct ~2GB + KV cache ~1GB + 1GB activation buffer = ~4GB minimum. Throughput-bound work; cheap GPUs (RTX 3060 / 4060 / etc) at ~$0.20/hr fit fine. min_reliability lower than lean-theorist's 0.95 because these are corpus-throughput workers — occasional sweep failures are acceptable; the trust-epoch + artifact-grounding gate (W.107/W.110) catches anomalies downstream."
    }
  }

description:
GIF-to-Sprite — Convert animated GIFs into holographic sprites
Installed via HoloClaw Shelf. Handles all 4 GIF disposal methods.

Pipeline: @animated_texture → @segment → @depth_estimation → @holographic_sprite
Temporal smoothing via EMA (alpha=0.8) eliminates depth flicker.

@see W.150: GIF temporal coherence requires EMA smoothing
@see G.149.01: GIF Disposal Methods Break Frame Extraction

snippet:
object "HolographicSprite" {
    @animated_texture {
      src: $gifSrc
      fps: 24
      max_frames: 500
    }
    @segment { model: "rembg", remove_background: true }
    @depth_estimation {
      model: "depth-anything-v2-small"
      backend: "webgpu"
      temporal_smoothing: $temporalAlpha
    }
    @holographic_sprite {
      depth_scale: $depthScale
      render_mode: $renderMode
    }
    @billboard { mode: "camera-facing" }

    position: [0, 1.5, -2]
    scale: [2, 2, 1]
  }

description:
Photo-to-Hologram — Convert any image into a 3D holographic panel
Installed via HoloClaw Shelf. Uses depth estimation + displacement.

Pipeline: @image → @segment → @depth_estimation → @displacement → @billboard
Progressive: instant flat image → depth-displaced 3D in <1s

@see W.148: Browser-native depth estimation is production-ready
@see P.148.01: Progressive Hologram Enhancement

snippet:
object "HologramPanel" {
    @image { src: $imageSrc }
    @segment { model: "rembg", remove_background: true }
    @depth_estimation {
      model: "depth-anything-v2-small"
      backend: "webgpu"
      max_resolution: 512
      cache: true
    }
    @displacement {
      scale: $depthScale
      segments: $segments
      auto_segments: true
    }
    @depth_to_normal
    @billboard { mode: "camera-facing" }

    position: [0, 1.5, -2]
    scale: [2, 2, 1]
  }

object "VideoHologram" {
    @video {
      src: $videoSrc
      autoplay: true
      loop: true
      muted: true
    }
    @depth_sequence {
      model: "depth-anything-v2-small"
      backend: "webgpu"
      consistency: "temporal"
      temporal_smoothing: $temporalAlpha
    }
    @displacement {
      scale: $depthScale
      segments: 64
    }

    position: [0, 1.5, -2]
    scale: [3, 1.7, 1]
  }

object "Worker" {
    @behavior_tree {
      root: {
        type: "sequence",
        name: "stdlib_demo",
        children: [
          // Step 1: Read a known file using fs_read
          {
            type: "action",
            name: "read_package_json",
            action: "fs_read",
            params: {
              path: "package.json",
              into: "pkg"
            }
          },

          // Step 2: Check if tsconfig exists using fs_exists
          {
            type: "action",
            name: "check_tsconfig",
            action: "fs_exists",
            params: {
              path: "tsconfig.json",
              into: "tsconfig"
            }
          },

          // Step 3: Write a temp file using fs_write
          {
            type: "action",
            name: "write_temp",
            action: "fs_write",
            params: {
              path: "data/stdlib-demo-output.txt",
              content: "Hello from stdlib-demo.hsplus!",
              into: "written"
            }
          },

          // Step 4: Run a shell command using process_exec
          {
            type: "action",
            name: "run_echo",
            action: "process_exec",
            params: {
              cmd: "echo",
              args: ["stdlib", "works"],
              into: "echo"
            }
          }
        ]
      }
    }
  }

