        rangeMapHorizontalOuter: {
          inputMaxValue: 90
          outputScale: 10
        }
        rangeMapVerticalDown: {
          inputMaxValue: 90
          outputScale: 10
        }
        rangeMapVerticalUp: {
          inputMaxValue: 90
          outputScale: 10
        }
      }
    }

    state {
      speaking: false
      currentEmotion: "neutral"
      isWaving: false
    }

    on_init() {
      // Activate idle blend tree
      skeleton.activateBlendTree("locomotion")
      skeleton.setParameter("speed", 0.0)

      // Start auto-blink
      morph.startAutoBlink()

      // Set initial expression
      morph.applyPreset("neutral")
    }

    on_event("speak", text) {
      state.speaking = true

      // Enable lip sync
      // (Visemes will be driven by TTS engine)

      // Optional: gesture animation based on speech length
      if (text.length > 100) {
        skeleton.play("wave")
        state.isWaving = true
      }
    }

    on_event("stopSpeaking") {
      state.speaking = false
      state.isWaving = false
      morph.clearVisemes()
    }

    on_event("setEmotion", emotion) {
      state.currentEmotion = emotion
      morph.blendToPreset(emotion, 0.5)
    }

    on_event("walk", speed) {
      skeleton.setParameter("speed", speed)
    }

    on_event("gesture", type) {
      if (type == "wave") {
        skeleton.play("wave")
      } else if (type == "celebrate") {
        skeleton.play("celebrate")
        morph.blendToPreset("happy")
      }
    }
  }

