object "Announcer" {
    @speech(
      voice: "deep_neutral",
      spatial: true,
      falloff: "inverse_square",
      max_range: 20,
      events: {
        "on_first_target_hit": "First hit! Keep going.",
        "on_all_targets_cleared": "Zone clear — impressive.",
        "on_wall_demolished": "The wall is down. Perfect.",
        "on_high_velocity_throw": "That one had some heat on it."
      },
      tts_provider: "edge_tts",
      pitch: -0.15,
      speed: 0.95
    )
    position: [0, 5.5, -9.5]
    geometry: "sphere"
    scale: 0.05
    material: { baseColor: "#1a237e", emissive: "#3949ab", emissiveIntensity: 0.6, opacity: 0.0 }
  }

object "MainLight" {
    type: "directional_light"
    direction: [-0.4, -0.7, -0.5]
    color: "#ffffff"
    intensity: 0.7
  }

object "TutorialState" {
    state {
      current_step: 1
      steps_completed: 0
    }

    action advance() {
      state.current_step++
      state.steps_completed++
      trigger "step_completed"
    }
  }

template "ProgressDot" {
    @glowing

    geometry: "cylinder"
    scale: [0.3, 0.1, 0.3]

    state {
      completed: false
    }
  }

object "WelcomeSign" {
    @glowing

    position: [0, 2.5, -3]
    scale: [3, 0.5, 0.1]
    geometry: "cube"
    color: "#00ff88"
    emissive: "#00ff88"
    emissiveIntensity: 0.5
  }

object "Step1Cube" {
    @pointable

    position: [-3, 1, 0]
    scale: [0.8, 0.8, 0.8]
    geometry: "cube"
    material: { baseColor: "#ff6b6b", roughness: 0.4, metallic: 0.2 }
    emissive: "#330a0a"
    emissiveIntensity: 0.25

    on_point() {
      flash_color("#ffffff", 200ms)
      TutorialState.advance()
    }
  }

object "Step2Orb" {
    @grabbable

    position: [0, 1, 0]
    scale: [0.6, 0.6, 0.6]
    geometry: "sphere"
    material: { baseColor: "#4ecdc4", roughness: 0.3, metallic: 0.35 }
    emissive: "#0a2a28"
    emissiveIntensity: 0.3

    on_grab() {
      pulse_scale(1.2, 100ms)
      TutorialState.advance()
    }
  }

object "Step3Animated" {
    @animated

    position: [3, 1, 0]
    scale: [0.7, 0.7, 0.7]
    geometry: "sphere"
    material: { baseColor: "#ffe66d", roughness: 0.35, metallic: 0.25 }
    emissive: "#332a0a"
    emissiveIntensity: 0.3
    animate: "float"
    animSpeed: 1
  }

object "Floor" {
    @collidable

    position: [0, 0, 0]
    scale: [10, 0.1, 10]
    geometry: "cube"
    material: { baseColor: "#2d3436", roughness: 0.85, metallic: 0.05 }
  }

object "Progress1" using "ProgressDot" {
    position: [-3, 0.2, 2]
    color: "#00ff00"
    emissive: "#00ff00"
    emissiveIntensity: 1
    state { completed: true }
  }

object "Progress2" using "ProgressDot" {
    position: [0, 0.2, 2]
    color: "#444444"
  }

object "Progress3" using "ProgressDot" {
    position: [3, 0.2, 2]
    color: "#444444"
  }

description:
============================================================================
Export Pipeline Examples -- Interoperability Showcase
============================================================================
Demonstrates HoloScript's cross-platform export traits. Each object
is tagged for one or more industry-standard formats, enabling a
single .holo source to target USD, glTF, FBX, and MaterialX.

Traits covered (6 traits, previously 0% coverage):
@usd            -- Pixar Universal Scene Description export
@gltf           -- Khronos glTF 2.0 export
@fbx            -- Autodesk FBX interchange
