    lightType: "point"
    color: "#ffffff"
    intensity: 1.0
    position: { x: 0, y: 3, z: 0 }
  }

template "ClickableTarget" {
    @interactive

    geometry: "sphere"
    radius: 0.4

    state {
      isActive: true
      hitCount: 0
      lastHitTime: 0
    }

    on_click(event) {
      if (!this.state.isActive) return;
      if (!state.isGameActive) return;

      // Increment local hit count
      this.state.hitCount += 1;
      this.state.lastHitTime = Date.now();

      // Award points (base 10, bonus for consecutive hits)
      const points = 10 + (this.state.hitCount - 1) * 2;
      actions.hitTarget(this.name, points);

      // Visual feedback
      this.playAnimation("pulse");
      this.playSound("hit");

      // Temporary disable
      this.state.isActive = false;
      setTimeout(() => {
        this.state.isActive = true;
      }, 500);
    }

    on_pointer_enter(event) {
      if (this.state.isActive && state.isGameActive) {
        // Highlight effect
        this.emission = this.color;
      }
    }

    on_pointer_exit(event) {
      // Remove highlight
      this.emission = "#000000";
    }
  }

object "Floor" {
    geometry: "plane"
    color: "#2a2a3a"
    width: 20
    height: 20
    position: { x: 0, y: 0, z: 0 }

    on_click(event) {
      // Clicking floor counts as miss
      actions.missedShot();
    }
  }

object "RedTarget" using "ClickableTarget" {
    color: "#ff4444"
    position: { x: -2, y: 1.5, z: -5 }
  }

object "GreenTarget" using "ClickableTarget" {
    color: "#44ff44"
    position: { x: 0, y: 1.5, z: -5 }
  }

object "BlueTarget" using "ClickableTarget" {
    color: "#4444ff"
    position: { x: 2, y: 1.5, z: -5 }
  }

object "MainLight" {
    type: "light"
    lightType: "point"
    color: "#ffffff"
    intensity: 1.0
    position: { x: 0, y: 4, z: 0 }
  }

object "ScoreDisplay" {
    type: "ui"
    uiType: "text"
    position: { x: 10, y: 10 }
    fontSize: 24
    color: "#ffffff"

    // Reactive binding
    bind: {
      text: "`Score: ${state.score}`"
    }
  }

object "TimerDisplay" {
    type: "ui"
    uiType: "text"
    position: { x: 10, y: 40 }
    fontSize: 24

    bind: {
      text: "`Time: ${computed.timeRemainingFormatted}`",
      color: "state.timeRemaining <= 10 ? '#ff4444' : '#ffffff'"
    }
  }

object "AccuracyDisplay" {
    type: "ui"
    uiType: "text"
    position: { x: 10, y: 70 }
    fontSize: 18
    color: "#aaaaaa"

    bind: {
      text: "`Accuracy: ${computed.accuracy}%`"
    }
  }

object "StatusDisplay" {
    type: "ui"
    uiType: "text"
    position: { x: 10, y: 100 }
    fontSize: 20
    color: "#44ff44"

    bind: {
      text: "computed.gameStatus"
    }
  }

object "StartButton" {
    type: "ui"
    uiType: "button"
    text: "Start Game"
    position: { x: 10, y: 140 }
    width: 120
    height: 40

    onClick: () => {
      actions.startGame();
    }

    // Hide when game is active
    bind: {
      visible: "!state.isGameActive || state.timeRemaining <= 0"
    }
  }

description:
The Amber Hall — Gothic Cathedral at Golden Hour (A-009 refresh 2026-05-18)

Original intent preserved: caustics, god rays, cascaded shadows, backlit
surfaces, and ambient glow — all the advanced lighting phenomena in one space.

Refresh adds:
@tapestry   — linen banners hang from triforium arches, dyed crimson and gold
@canopy     — fabric baldachin suspended above the high altar
@renaissance — the hall is a 15th-century nave at the height of its patronage
@relic      — a glass reliquary on the altar glows with stored luminance

Scene story: late afternoon, the sun angles through south rose windows at 32°.
Colored rays pierce the nave dust into defined shafts. The font on the crossing
throws caustic nets across the mosaic floor. Six tall beeswax candles encircle
the reliquary, their heat hazing the air above. Every surface — limestone pillar,
gilded tapestry thread, polished floor tile — is a collaborator in the light show.

@version 5.2.0
@category lighting, cathedral, golden-hour
@traits @tapestry @canopy @renaissance @relic

snippet:
object "NavFloor" using "MosaicFloor" {
    geometry: "plane"
    width: 18.0
    height: 48.0
    subdivisions: 8
    position: [0, 0, 0]
    rotation: [-90, 0, 0]
    @collidable { friction: 0.7 }
    // Caustic receiver — high-res subdivided for smooth irradiance projection
    caustic_receiver: true
    shadow_receiver: true
  }

