object "HologramDisplay" {
    @custom_shader {
      vertex: "varying vec2 vUv;\nvarying vec3 vNormal;\nvoid main() {\n  vUv = uv;\n  vNormal = normalMatrix * normal;\n  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);\n}"
      fragment: "uniform float time;\nuniform vec3 baseColor;\nvarying vec2 vUv;\nvarying vec3 vNormal;\nvoid main() {\n  float scanline = sin(vUv.y * 100.0 + time * 5.0) * 0.1 + 0.9;\n  float edge = pow(1.0 - abs(dot(vNormal, vec3(0.0, 0.0, 1.0))), 2.0);\n  vec3 color = baseColor * scanline + vec3(0.0, 0.5, 1.0) * edge;\n  float alpha = 0.6 + edge * 0.4;\n  gl_FragColor = vec4(color, alpha);\n}"
      uniforms: {
        time: { type: "float", value: 0.0 },
        baseColor: { type: "vec3", value: [0.0, 0.8, 1.0] }
      }
      transparent: true
      side: "double"
    }

    geometry: "cube"
    position: [4, 1.5, 0]
    scale: [1.5, 2, 0.1]

    @on_update: (delta) => {
      this.uniforms.time += delta;
    }
  }

