snippet:
object "HapticExperience" {
    @haptic_feedback {
      mode: "continuous"
      intensity: 0.5
      pattern: "heartbeat"
      device: "controller"
    }

    @force_feedback {
      enabled: true
      max_force_n: 5
      direction: "opposing"
      surface_simulation: true
    }

    @thermal_feedback {
      temperature: 25
      range: [10, 40]
      rate_of_change: 2
      zones: ["palm", "fingertips"]
    }

    @texture_feedback {
      pattern: "rough_stone"
      frequency: 200
      amplitude: 0.3
      spatial: true
    }

    @vibration {
      frequency: 150
      amplitude: 0.4
      duration: 100
      waveform: "sine"
    }

    @pressure {
      level: 0.5
      distribution: "uniform"
      feedback_device: "glove"
    }

    @wind_simulation {
      speed: 5
      direction: [1, 0, 0]
      fan_zones: ["face", "arms"]
      gusts: true
    }

    @scent_emitter {
      scent: "pine_forest"
      intensity: 0.3
      radius: 3
      duration: 30
      device: "olfactory_display"
    }

    @taste_signal {
      flavor: "sweet"
      intensity: 0.2
      electrode_pattern: "tip_of_tongue"
    }

    @spatial_audio_3d {
      hrtf: true
      distance_model: "inverse"
      rolloff: 1.0
      doppler: true
      reverb: "medium_room"
    }

    @bone_conduction {
      frequency_range: [200, 4000]
      volume: 0.4
      spatial: true
