      level 0 {
        mesh: "models/oak_high.glb"
        material: "TreeBark"
        vertex_count: 12000
      }
      level 30 {
        mesh: "models/oak_mid.glb"
        material: "TreeBark"
        vertex_count: 3000
      }
      level 100 {
        mesh: "models/oak_low.glb"
        material: "TreeBark"
        vertex_count: 400
      }
      level 300 {
        mesh: "models/oak_billboard.glb"
        vertex_count: 4
      }
    }

    render {
      cast_shadows: true
      receive_shadows: true
      culling: "frustum"
      layer: "vegetation"
      wind_sway: true
      wind_strength: 1.2
    }
  }

