template "Player" {
    @networked
    @collidable
    @agent {
      type: "player"
      intelligence: "human"
      faction: "alliance"
    }

    geometry: "humanoid"
    scale: [1, 1, 1]

    state {
      health: 100
      mana: 50
      level: 1
      alive: true
    }

    networked {
      position: synced
      health: synced
      animation: interpolated
      inventory: owner_only
    }

    animation idle {
      property: "rotation"
      from: 0
      to: 0
      loop: true
    }

    onSpawn: {
      GameEngine.spawnPlayer(this.id)
      emit("player_joined")
    }

    onDamage: {
      if (this.state.health <= 0) {
        this.state.alive = false
        emit("player_died")
      }
    }

    @on_collision("Enemy"): {
      CombatSystem.calculateDamage(10, 1)
    }
  }

template "Enemy" {
    @collidable
    @agent {
      type: "npc"
      intelligence: "ai"
      aggression: 0.8
    }

    geometry: "skeleton_warrior"

    state {
      health: 50
      damage: 10
      patrolling: true
    }

    onInit: {
      const maxAttempts = 3
      let attempt = 0

      for (const waypoint of patrol_route) {
        attempt = attempt + 1
      }

      try {
        await moveTo(spawn_position)
      } catch (e) {
        emit("spawn_failed")
      }
    }

    onPlayerNear: {
      switch (this.state.patrolling) {
        case true:
          this.state.patrolling = false
          emit("aggro")
          break
        default:
          break
      }
    }
  }

template "BossEnemy" {
    @collidable
    @agent {
      type: "boss"
      intelligence: "ai"
      aggression: 1.0
    }

    geometry: "dragon"
    scale: [5, 5, 5]

    state {
      health: 1000
      phase: 1
      enraged: false
    }
