        probeCount: 300
        raysPerProbe: 512
        irradianceTexSize: 8
        visibilityTexSize: 16
        normalBias: 0.08
        hysteresis: 0.92
      }
      skyIntensity: 0.0
      specularOcclusion: 0.6
      supportDynamicObjects: true
    }
  }

