snippet:
object "wallet_connect_button" {
    @wallet {
      chains: ["ethereum", "polygon", "solana"]
      auto_connect: false
      persist_connection: true
      show_balance: true
      supported_tokens: ["ETH", "MATIC", "USDC", "SOL"]
    }
    @clickable {
      feedback: "visual"
    }
    @hoverable {
      color_on_hover: "#7209b7"
    }
    geometry: "cube"
    position: [4.5, 1.6, 0.0]
    scale: [0.6, 0.25, 0.1]
    color: "#4361ee"
    state {
      connected: false
      address: ""
      balance_eth: 0.0
      balance_usdc: 0.0
    }
    onWalletConnect: {
      set connected true
      set address event.address
      set balance_eth event.balances.ETH
      set balance_usdc event.balances.USDC
    }
    onWalletDisconnect: {
      set connected false
      set address ""
    }
  }

