template "ArtworkNFT" {
    @nft_asset {
      contract: "0x0000000000000000000000000000000000000000"
      standard: "ERC-721"
      chain: "polygon"
      metadata_uri: ""
      royalty_bps: 500
      max_supply: 10
    }
    @economy_primitive {
      list_price_arc: 50
    }
    @grabbable {
      hand: "both"
    }
    @hoverable {
      show_tooltip: true
      tooltip_text: ""
    }
    geometry: "plane"
    state {
      title: ""
      artist: ""
      edition: ""
      price_usd: 0.0
      price_eth: 0.0
      owner: "gallery"
      minted: false
      token_id: -1
    }
    onClick: {
      open_panel "artwork_detail" {
        title: state.title
        artist: state.artist
        edition: state.edition
        price_usd: state.price_usd
        price_eth: state.price_eth
      }
    }
    onPurchaseComplete: {
      set owner event.buyer_address
      set minted true
      set token_id event.token_id
      play_audio "purchase_success.ogg"
      spawn_effect "confetti" at self
    }
  }

