object "GalleryFloor" {
    @collidable

    geometry: "plane"
    position: [0, 0, 0]
    scale: [30, 1, 16]
    color: "#1a1a1a"
    material: "polished_concrete"
  }

object "BackWall" {
    @collidable

    geometry: "cube"
    position: [0, 2.5, -7]
    scale: [30, 5, 0.2]
    color: "#2a2a2a"
    material: "matte_plaster"
  }

object "Exhibit1_Label" {
    @billboard

    geometry: "plane"
    position: [-10, 3.8, -6.5]
    scale: [2.5, 0.3, 0.01]
    color: "#ffffff"
    text: "1. 3D Gaussian Splatting"
    fontSize: 0.1
  }

object "GaussianSplatScene" {
    @gaussian_splat(
      source: "captures/garden_scene.ply",
      splat_count: 2400000,
      sh_degree: 3,
      sort_mode: "gpu_radix",
      render_mode: "splatting",
      max_splats_visible: 1500000,
      opacity_threshold: 0.005,
      scale_modifier: 1.0,
      antialiasing: true
    )
    @clickable

    position: [-10, 1.2, -4]
    scale: [2, 2, 2]
    rotation: [0, 30, 0]

    state {
      quality: "high"
    }

    on_click() {
      if (state.quality == "high") {
        state.quality = "medium"
        gaussian_splat.max_splats_visible = 800000
      } else if (state.quality == "medium") {
        state.quality = "low"
        gaussian_splat.max_splats_visible = 400000
      } else {
        state.quality = "high"
        gaussian_splat.max_splats_visible = 1500000
      }
      ui.toast("Quality: " + state.quality)
    }
  }

object "GaussianSplatInfo" {
    @billboard

    geometry: "plane"
    position: [-10, 0.15, -2]
    scale: [2.2, 0.5, 0.01]
    color: "#333333"
    opacity: 0.8
    text: "2.4M Gaussians | SH degree 3\nReal-time novel view synthesis\nClick to cycle quality"
    fontSize: 0.04
  }

object "Exhibit2_Label" {
    @billboard

    geometry: "plane"
    position: [-5, 3.8, -6.5]
    scale: [2.5, 0.3, 0.01]
    color: "#ffffff"
    text: "2. Neural Radiance Field (NeRF)"
    fontSize: 0.1
  }

object "NeRFPortrait" {
    @nerf(
      model: "captures/portrait_nerf.msgpack",
      network: "instant_ngp",
      resolution: [512, 512],
      samples_per_ray: 128,
      near_plane: 0.2,
      far_plane: 6.0,
      background: "transparent",
      cache_mode: "baked_texture",
      lod_levels: 3
    )
    @rotatable

    position: [-5, 1.5, -4]
    scale: [1.5, 1.5, 1.5]
    rotation: [0, 0, 0]

    state {
      auto_rotate: true
    }

    animation auto_spin {
      property: "rotation.y"
      from: 0
      to: 360
      duration: 24000
      loop: infinite
      easing: "linear"
    }

    on_init() {
      if (state.auto_rotate) {
        play("auto_spin")
      }
    }

    on_click() {
      state.auto_rotate = !state.auto_rotate
      if (state.auto_rotate) {
        play("auto_spin")
      } else {
        stop("auto_spin")
      }
    }
  }

object "NeRFInfo" {
    @billboard

    geometry: "plane"
    position: [-5, 0.15, -2]
    scale: [2.2, 0.5, 0.01]
    color: "#333333"
    opacity: 0.8
    text: "Instant-NGP | 512x512 render\n128 samples/ray | Baked cache\nClick to toggle auto-rotate"
    fontSize: 0.04
  }

object "Exhibit3_Label" {
    @billboard

    geometry: "plane"
    position: [0, 3.8, -6.5]
    scale: [2.5, 0.3, 0.01]
    color: "#ffffff"
    text: "3. Volumetric Video"
    fontSize: 0.1
  }

object "DancerCapture" {
    @volumetric_video(
      source: "captures/dancer_performance.draco",
      codec: "draco_sequence",
      fps: 30,
      duration: 12.5,
      loop: true,
      autoplay: true,
      mesh_quality: "high",
      texture_resolution: 2048,
      preload_frames: 60,
      audio_track: "captures/dancer_audio.ogg"
    )
    @spatial_audio

    position: [0, 0, -4]
    scale: [1, 1, 1]

    state {
      playing: true
      playback_speed: 1.0
    }

    spatial_audio: {
      refDistance: 2.0
      maxDistance: 12.0
      rolloffFactor: 1.0
    }

    on_click() {
      state.playing = !state.playing
      if (state.playing) {
        volumetric_video.play()
      } else {
        volumetric_video.pause()
      }
    }
  }

