object "AnchorPlacer" {
    @spatial_anchor {
      persistent: true
      ttl_hours: 720
      accuracy: "high"
    }

    @cloud_anchor {
      provider: "azure_spatial_anchors"
      account_id: "env:AZURE_SPATIAL_ACCOUNT"
