    material: {
      baseColor: "#0f0818"
      metallic: 0.05
      roughness: 0.0
      transmission: 0.76
      ior: 1.54
    }
    @crystalline {
      system: "hexagonal"
      clarity: 0.82
      charge_bleed_receptive: true
    }
    @glowing { color: "#6030c8", radius: 1.6, falloff: "smooth" }
    @neon_glow {
      vein_color: "#20eebb"
      vein_width: 0.004
      vein_density: 0.5
      pulse_rate: 0.9
    }
    castShadow: true
    receiveShadow: true
  }

