      position: "bottom"
      max_chars: 80
      fade_delay_s: 4.0
      font_size: 18
      background_opacity: 0.65
    }

    @spatial_audio_cue {
      event: "screen_activated"
      sound: "audio/screen_activate.wav"
      volume: 0.7
      max_distance: 8.0
      rolloff: "linear"
    }
  }

