snippet:
object "AmbientHVAC" {
    position: [0, 3.5, 0]
    @spatial_audio_cue {
      sound: "audio/hvac_room_tone.wav"
      volume: 0.18
      loop: true
      max_distance: 10.0
      rolloff: "logarithmic"
      auto_play: true
    }
  }

object "MeetingRoomVoiceZone" {
    geometry: "box"
    visible: false
    position: [0, 2.5, 0]
    scale: [10, 5, 10]

    @spatial_voice {
      range: 20
      rolloff: "inverse"
      rolloff_factor: 1.0
      hrtf: true
      vad_threshold: -40
      echo_cancellation: true
      noise_suppression: true
      max_streams: 8
    }
  }

object "PresentationScreen" {
    geometry: "plane"
    position: [0, 2.0, -4.5]
    scale: [4.0, 2.25, 0.05]
    material: { baseColor: "#0a0a0a", roughness: 0.2, metallic: 0.1 }

    @voice_input {
      mode: "push-to-talk"
      confidenceThreshold: 0.75
      languages: ["en-US"]
      showTranscript: true
      audioFeedback: true
      timeout: 10000
      commands: [
        { phrase: "next slide", action: "screen.next" },
        { phrase: "previous slide", action: "screen.prev" },
        { phrase: "zoom in", action: "screen.zoom_in" },
        { phrase: "zoom out", action: "screen.zoom_out" },
        { phrase: "reset view", action: "screen.reset" },
        { phrase: "mute audio", action: "audio.mute" },
        { phrase: "unmute audio", action: "audio.unmute" }
      ]
    }

    // Screen content placeholder
    texture: "textures/presentation_slide_01.png"
  }

object "RemotePeerAvatar" {
    geometry: "capsule"
    position: [2.0, 0.9, 1.5]
    scale: [0.4, 0.9, 0.4]
    material: { baseColor: "#4488ff", roughness: 0.5, metallic: 0.0 }

    // Visual indicator when peer is speaking
    @spatial_voice {
      range: 20
      rolloff: "inverse"
      hrtf: true
      vad_threshold: -40
      echo_cancellation: true
      noise_suppression: true
      max_streams: 1
    }
  }

object "RoomFloor" {
    @audio_material(absorption_low: 0.25, absorption_mid: 0.35, absorption_high: 0.45)
    @collidable
    geometry: "plane"
    position: [0, 0, 0]
    scale: [12, 1, 12]
    material: { baseColor: "#2a2a2a", roughness: 0.8, metallic: 0.0 }
  }

object "RoomCeiling" {
    @audio_material(absorption_low: 0.15, absorption_mid: 0.20, absorption_high: 0.25)
    geometry: "plane"
    position: [0, 5, 0]
    scale: [12, 1, 12]
    material: { baseColor: "#e8e8e8", roughness: 0.6, metallic: 0.0 }
  }

object "WallFront" {
    @audio_material(absorption_low: 0.10, absorption_mid: 0.12, absorption_high: 0.15)
    @audio_occlusion(transmission_loss: 30, frequency_dependent: true)
    @collidable
    geometry: "plane"
    position: [0, 2.5, -6]
    scale: [12, 5, 1]
    material: { baseColor: "#d0d0d0", roughness: 0.7, metallic: 0.0 }
  }

object "WallBack" {
    @audio_material(absorption_low: 0.10, absorption_mid: 0.12, absorption_high: 0.15)
    @audio_occlusion(transmission_loss: 30, frequency_dependent: true)
    @collidable
    geometry: "plane"
    position: [0, 2.5, 6]
    scale: [12, 5, 1]
    material: { baseColor: "#d0d0d0", roughness: 0.7, metallic: 0.0 }
  }

object "WallLeft" {
    @audio_material(absorption_low: 0.10, absorption_mid: 0.12, absorption_high: 0.15)
    @audio_occlusion(transmission_loss: 30, frequency_dependent: true)
    @collidable
    geometry: "plane"
    position: [-6, 2.5, 0]
    scale: [1, 5, 12]
    material: { baseColor: "#d0d0d0", roughness: 0.7, metallic: 0.0 }
  }

object "WallRight" {
    @audio_material(absorption_low: 0.10, absorption_mid: 0.12, absorption_high: 0.15)
    @audio_occlusion(transmission_loss: 30, frequency_dependent: true)
    @collidable
    geometry: "plane"
    position: [6, 2.5, 0]
    scale: [1, 5, 12]
    material: { baseColor: "#d0d0d0", roughness: 0.7, metallic: 0.0 }
  }

template "HumanSteward" {
    @controllable
    @physics
    @collidable
    @health_system
    geometry: "humanoid"
    scale: [0.5, 1.8, 0.5]
    state { hp: 100, breath: 100, reputation: 0, inhabited_by: "human" }
