template "Spinner" {
    @animated
    @collidable
    geometry: "box"
    color: "#9b59b6"
    animate: "spin"
    animSpeed: 0
    points: 10

    @on_collision: (ball) => {
      this.animSpeed += 2;
      GameState.addScore(this.points);
