template "Door" {
    @static_body_3d
    @animatable
    geometry: "model/door.glb"

    state {
      open: false
      required_plates: 1
      active_plates: 0
    }

    animation "open" {
      property: "position.y"
      from: 0
      to: 3
      duration: 1000
      easing: "ease_out"
    }

    on_signal: {
      match signal_name:
        "plate_activated":
          this.state.active_plates += 1
        "plate_deactivated":
          this.state.active_plates -= 1
      
      if this.state.active_plates >= this.state.required_plates:
        play_animation("open")
      else:
        play_animation("open", reverse=true)
    }
  }

