@version 5.0.0
@format .hsplus (behavior — requires onSensorUpdate and streaming event hooks)
@traits @iot_sensor, @digital_twin, @mqtt_bridge, @telemetry

snippet:
object "kpi_dashboard" {
    @telemetry {
      subscribe: ["temp-cnc-*", "vib-cnc-*", "factory-cnc-*"]
      aggregate: true
      window_ms: 60000
    }
    geometry: "plane"
    position: [0, 2.4, -8.5]
    scale: [6.0, 2.0, 1.0]
    color: "#0d1b2a"
    state {
      avg_temp: 0.0
      max_vib: 0.0
      total_power_kw: 0.0
      machines_running: 0
    }
    onTelemetryAggregate: {
      set avg_temp event.aggregates.temperature.mean
      set max_vib event.aggregates.vibration.max
      set total_power_kw event.aggregates.power_kw.sum
      set machines_running event.aggregates.status.count_active
    }
  }

description:
Multiplayer Networking Traits — @networked, @synced, @persistent, @owned, @replicated, @host_only

Demonstrates the networking trait family in a collaborative 3D whiteboard
room where multiple users can draw, place sticky notes, and move objects,
with full state sync across peers.

@version 5.0.0
@format .hsplus (behavior — requires per-event sync callbacks)
@traits @networked, @synced, @persistent, @owned, @replicated, @host_only

snippet:
object "session" {
    @networked {
      room_id: "collab-room-default"
      max_peers: 12
      transport: "webrtc"
      ice_servers: ["stun:stun.l.google.com:19302"]
    }
    state {
      peer_count: 0
      host_id: ""
    }
    onPeerJoin: {
      increment peer_count
      broadcast "peer_join" { id: event.peer_id, ts: event.timestamp }
    }
    onPeerLeave: {
      decrement peer_count
      release_owned_objects event.peer_id
    }
  }

description:
Multiplayer Networking Traits — @networked, @synced, @persistent, @owned, @replicated, @host_only

Demonstrates the networking trait family in a collaborative 3D whiteboard
room where multiple users can draw, place sticky notes, and move objects,
with full state sync across peers.

@version 5.0.0
@format .hsplus (behavior — requires per-event sync callbacks)
@traits @networked, @synced, @persistent, @owned, @replicated, @host_only

snippet:
template "SyncedStickyNote" {
    @synced {
      properties: ["position", "rotation", "state.text", "state.color"]
      interpolate: true
      interpolation_ms: 80
    }
    @owned {
      transfer_on_release: true
      owner_can_delete: true
    }
    @grabbable {
      hand: "both"
    }
    geometry: "plane"
    state {
      text: ""
      color: "#ffd166"
      author: ""
    }
    onGrab: {
      claim_ownership self
    }
    onRelease: {
      sync_now self
    }
    onChange "state.text": {
      sync_now self
    }
  }

